package cn.sixnine.filmlog;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;

/** Native dialogs and actual saves, using the isolated UI test host/workspace. */
public final class CameraEditorInstrumentation extends Instrumentation {
    private RollWizardInstrumentation.Host host;
    private Dialog editor;
    private Bundle state;
    private String saved="";
    private int cancelled;
    private boolean night;private float fontScale=1f;
    interface Action{void run()throws Exception;}
    private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private void main(Action action)throws Exception{Throwable[] bad={null};runOnMainSync(()->{try{action.run();}catch(Throwable e){bad[0]=e;}});waitForIdleSync();if(bad[0]!=null)throw new RuntimeException(bad[0]);}
    private void tree(View v,List<View> all){all.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)tree(((ViewGroup)v).getChildAt(i),all);}
    private List<View> views(){List<View> all=new ArrayList<>();tree(editor.getWindow().getDecorView(),all);return all;}
    private Button button(String label){if(label.equals("‹ 返回")){for(View v:views())if(v instanceof Button&&"返回".contentEquals(v.getContentDescription()))return (Button)v;}for(View v:views())if(v instanceof Button&&((Button)v).getText().toString().equals(label))return (Button)v;throw new AssertionError("missing button "+label);}
    private EditText input(String label){for(View v:views())if(v instanceof EditText&&label.contentEquals(v.getContentDescription()))return (EditText)v;throw new AssertionError("missing input "+label);}
    private void model(String query){input("搜索品牌或型号").setText(query);for(View v:views())if(v instanceof ListView){ListView list=(ListView)v;check(list.getAdapter().getCount()>0,"model search");list.performItemClick(list.getAdapter().getView(0,null,list),0,0);return;}throw new AssertionError("missing models list");}
    private void open(CatalogStore.Entry old){state=new Bundle();editor=CameraEditor.show(host,host.logs,state,old,id->saved=id,()->cancelled++);}
    private void shot(String name)throws Exception{waitForIdleSync();android.os.SystemClock.sleep(300);android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"native screenshot");File dir=new File(getTargetContext().getFilesDir(),"camera-logo-shots");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    private Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    @Override public void onCreate(Bundle args){super.onCreate(args);if(args!=null){night="true".equals(args.getString("night"));fontScale=Float.parseFloat(args.getString("fontScale","1"));}start();}
    @Override public void onStart(){Bundle out=new Bundle();try{check(getTargetContext().getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated UI package");android.content.res.Configuration configuration=new android.content.res.Configuration();configuration.uiMode=night?android.content.res.Configuration.UI_MODE_NIGHT_YES:android.content.res.Configuration.UI_MODE_NIGHT_NO;configuration.fontScale=fontScale;RollWizardInstrumentation.Host.testConfiguration=configuration;host=(RollWizardInstrumentation.Host)startActivitySync(new Intent(getTargetContext(),RollWizardInstrumentation.Host.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("testNight",night).putExtra("testFont",fontScale));waitForIdleSync();CatalogStore catalog=new CatalogStore(host.logs);
        main(()->open(null));shot("01-models");main(()->{model("Nikon FE2");check(state.getString("model").equals("Nikon FE2")&&state.getString("logo").equals("initial-Nikon"),"FE2 brand fallback");});shot("02-confirm");main(()->button("更换 Logo  ›").performClick());shot("03-logo");main(()->{button("使用通用相机图标").performClick();button("‹ 返回").performClick();check(state.getString("logo").equals("initial-Nikon"),"cancel retains logo");for(View v:views())if(v instanceof CheckBox&&((CheckBox)v).getText().toString().equals("首页显示品牌名称"))((CheckBox)v).setChecked(true);button("保存相机").performClick();check(!saved.isEmpty(),"real camera save");});final String fe2=saved;check(catalog.entry(fe2,"camera").cameraLogo.equals("initial-Nikon"),"stored chosen logo");check(catalog.entry(fe2,"camera").cameraShowBrand,"display preference saved by native editor");
        main(()->{open(catalog.entry(fe2,"camera"));button("更多信息  ＋").performClick();input("昵称（可选）").setText("未保存的昵称");button("‹ 返回").performClick();check(catalog.entry(fe2,"camera").name.equals("Nikon FE2"),"cancel does not save edits");open(null);button("没有找到？手动添加").performClick();button("保存相机").performClick();check(editor.isShowing(),"empty model blocks save");input("相机型号").setText("My custom camera");button("保存相机").performClick();check(catalog.entry(saved,"camera").cameraLogo.isEmpty(),"generic custom camera save");});
        main(()->{catalog.saveCamera(fe2,"Nikon FE2","银色机身","35 mm","","",false,"initial-Nikon");Bundle draft=new Bundle();draft.putString("stock","Test stock");draft.putString("format","35 mm");draft.putString("iso","400");draft.putString("capacity","36");RollWizard wizard=new RollWizard(host,host.logs,draft,()->{},id->{});wizard.show();java.lang.reflect.Method choose=RollWizard.class.getDeclaredMethod("chooseCamera");choose.setAccessible(true);choose.invoke(wizard);AlertDialog picker=(AlertDialog)field(wizard,"cameraDialog");List<View> all=new ArrayList<>();tree(picker.getWindow().getDecorView(),all);for(View v:all)if(v instanceof EditText)((EditText)v).setText("FE2");for(View v:all)if(v instanceof ListView){ListView list=(ListView)v;check(list.getAdapter().getCount()>0&&list.getAdapter().getItem(0).toString().contains("银色机身"),"model search finds owned nickname");}for(View v:all)if(v instanceof EditText)((EditText)v).setText("");for(View v:all)if(v instanceof Button&&((Button)v).getText().toString().equals("＋ 添加相机")){v.performClick();break;}editor=(Dialog)field(wizard,"cameraEditorDialog");check(editor!=null&&editor.isShowing(),"add camera from wizard");model("Nikon F3");button("保存相机").performClick();String cameraId=draft.getString("cameraId","");check(!cameraId.isEmpty()&&catalog.entry(cameraId,"camera").cameraLogo.equals("GT23/NIKON-F3"),"wizard returns with new stable camera selected");check(draft.getString("stock").equals("Test stock")&&draft.getString("iso").equals("400")&&draft.getString("capacity").equals("36"),"film draft unchanged");((Dialog)field(wizard,"dialog")).dismiss();});
        main(()->{LinearLayout page=new LinearLayout(host);page.setOrientation(1);page.setPadding(20,20,20,20);page.setBackgroundColor(host.getColor(R.color.ui_background));page.addView(new HomeRollCard(host,host.logs,host.logs.roll(catalog.manual(UUID.randomUUID().toString(),"Preview","Kodak Gold 200","Nikon FE2",200,36,"35 mm",fe2,"","original:kodak_gold_200")),()->{},()->{},()->{}),new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(host);scroll.addView(page);host.setContentView(scroll);});shot("04-home");main(()->host.finish());out.putString("stream","PASS: native model search/brand fallback/logo cancellation/save/edit cancellation/manual validation/generic camera; real wizard add/save/return selection preserves film draft; native screenshots saved to files/camera-logo-shots\n");finish(-1,out);
    }catch(Throwable bad){out.putString("stream",android.util.Log.getStackTraceString(bad));finish(0,out);}}
}
